    config: RepoConfig,
    data_source: DataSource,
    join_key_columns: List[str],
    feature_name_columns: List[str],
    timestamp_field: str,
    created_timestamp_column: Optional[str],
    start_date: datetime,
    end_date: datetime,
    data_source_reader: Callable[[DataSource, str], Table],
    data_source_writer: Callable[[pyarrow.Table, DataSource, str], None],
    staging_location: Optional[str] = None,
    staging_location_endpoint_override: Optional[str] = None,
) -> RetrievalJob:
    fields = join_key_columns + feature_name_columns + [timestamp_field]
    if created_timestamp_column:
        fields.append(created_timestamp_column)
    start_date = start_date.astimezone(tz=timezone.utc).replace(tzinfo=None)
    end_date = end_date.astimezone(tz=timezone.utc).replace(tzinfo=None)

    table = data_source_reader(data_source, str(config.repo_path))

    table = table.select(*fields)

    # TODO get rid of this fix
    if "__log_date" in table.columns:
        table = table.drop("__log_date")

    table = table.filter(
        ibis.and_(
            _comparable_timestamp(table[timestamp_field]) >= ibis.literal(start_date),
            _comparable_timestamp(table[timestamp_field]) <= ibis.literal(end_date),
        )
    )

    table = deduplicate(
        table=table,
        group_by_cols=join_key_columns,
        event_timestamp_col=timestamp_field,
        created_timestamp_col=created_timestamp_column,
    )

    return IbisRetrievalJob(
        table=table,
        on_demand_feature_views=[],
        full_feature_names=False,
        metadata=None,
        data_source_writer=data_source_writer,
        staging_location=staging_location,
        staging_location_endpoint_override=staging_location_endpoint_override,
        repo_path=str(config.repo_path),
    )


def _comparable_timestamp(column):
    """Cast a timestamp column for comparison with a window bound, keeping any zone.

    DuckDB 2 refuses to cast TIMESTAMPTZ_NS, which is what pandas writes by default, to a
    TIMESTAMP without a zone, and ibis reports that column's type as unknown.
    """
    column_type = column.type()
    if column_type.is_unknown():
        return column.cast(dt.Timestamp(timezone="UTC"))
    timezone = getattr(column_type, "timezone", None)
    return column.cast(dt.Timestamp(timezone=timezone) if timezone else "timestamp")


